//! The test PKI: certificates generated by OpenSSL (`tests/pki/generate.sh`, run with
//! `just test-pki`), so an implementation independent of this crate produces every
//! certificate the tests validate. The topology mirrors `gempki`'s `internal/testca`;
//! validity is fixed around [`TestPki::NOW`], so the files never go stale.

use crate::time::Timestamp;
use crate::{Certificate, parse_pem_certificates};

macro_rules! fixture {
    ($name:literal) => {
        load(include_str!(concat!("../tests/pki/", $name, ".pem")))
    };
}

fn load(pem: &str) -> Certificate {
    let mut certs = parse_pem_certificates(pem.as_bytes()).expect("fixture parses");
    assert_eq!(certs.len(), 1, "one certificate per fixture file");
    certs.remove(0)
}

/// The OpenSSL-generated test PKI; see `tests/pki/generate.sh` for the topology.
#[derive(Clone, Debug)]
pub(crate) struct TestPki {
    pub(crate) rca1: Certificate,
    pub(crate) sub_ca_hba: Certificate,
    pub(crate) ee_arzt: Certificate,
    pub(crate) ee_expired: Certificate,
    pub(crate) ee_not_yet_valid: Certificate,
    pub(crate) ee_revoked: Certificate,
    pub(crate) sub_ca_mixed: Certificate,
    pub(crate) ee_mixed: Certificate,
    pub(crate) sub_ca_expired: Certificate,
    pub(crate) ee_under_expired: Certificate,
    pub(crate) rca7: Certificate,
    pub(crate) sub_ca_komp: Certificate,
    pub(crate) ee_zeta: Certificate,
    pub(crate) ee_p521: Certificate,
    pub(crate) cross_rca1_for_rca7: Certificate,
    pub(crate) cross_rca7_for_rca1: Certificate,
    pub(crate) cross_rca1_not_rca: Certificate,
    pub(crate) rogue_root: Certificate,
    pub(crate) ee_rogue: Certificate,
    pub(crate) rca_rsa: Certificate,
    pub(crate) ee_rsa_pss: Certificate,
    pub(crate) sub_ca_pathlen0: Certificate,
    pub(crate) sub_sub_ca: Certificate,
    pub(crate) ee_deep: Certificate,
    pub(crate) ee_under_ee: Certificate,
}

impl TestPki {
    /// The instant the fixtures are built around: 2026-01-01T00:00:00Z.
    pub(crate) const NOW: Timestamp = Timestamp(1_767_225_600);

    pub(crate) fn new() -> Self {
        TestPki {
            rca1: fixture!("rca1"),
            sub_ca_hba: fixture!("sub-ca-hba"),
            ee_arzt: fixture!("ee-arzt"),
            ee_expired: fixture!("ee-expired"),
            ee_not_yet_valid: fixture!("ee-not-yet-valid"),
            ee_revoked: fixture!("ee-revoked"),
            sub_ca_mixed: fixture!("sub-ca-mixed"),
            ee_mixed: fixture!("ee-mixed"),
            sub_ca_expired: fixture!("sub-ca-expired"),
            ee_under_expired: fixture!("ee-under-expired"),
            rca7: fixture!("rca7"),
            sub_ca_komp: fixture!("sub-ca-komp"),
            ee_zeta: fixture!("ee-zeta"),
            ee_p521: fixture!("ee-p521"),
            cross_rca1_for_rca7: fixture!("cross-rca1-for-rca7"),
            cross_rca7_for_rca1: fixture!("cross-rca7-for-rca1"),
            cross_rca1_not_rca: fixture!("cross-rca1-not-rca"),
            rogue_root: fixture!("rogue-root"),
            ee_rogue: fixture!("ee-rogue"),
            rca_rsa: fixture!("rca-rsa"),
            ee_rsa_pss: fixture!("ee-rsa-pss"),
            sub_ca_pathlen0: fixture!("sub-ca-pathlen0"),
            sub_sub_ca: fixture!("sub-sub-ca"),
            ee_deep: fixture!("ee-deep"),
            ee_under_ee: fixture!("ee-under-ee"),
        }
    }
}

